sys_ws_operation.operation_script:
(function process(request, response) {
    var token = request.body.data.token;
    var pan = request.body.data.pan;

    var gr = new GlideRecord('x_birl3_clm_customer_secure_link');
    gr.addQuery('token', token);   // backend field is 'token'
    gr.query();

    if (!gr.next()) {
        response.setStatus(400);
        response.setBody({result: 'error', message: 'Invalid token'});
        return;
    }

    // Check if already used
    if (gr.u_used == true) {
        response.setStatus(400);
        response.setBody({result: 'error', message: 'This link has already been used'});
        return;
    }

    // Check expiry
    var now = new GlideDateTime();
    if (now.after(gr.expiry_date)) {
        gr.status = 'Expired';
        gr.update();
        response.setStatus(400);
        response.setBody({result: 'error', message: 'Link expired'});
        return;
    }

    // Verify PAN
    if (gr.pan == pan) {
        gr.status = 'Verified';
        gr.u_used = true;   // mark as used
        gr.update();
        response.setStatus(200);
        response.setBody({
            result: 'success',
            details: {
                customer: gr.customer + '',
                status: gr.status + ''
            }
        });
    } else {
        response.setStatus(400);
        response.setBody({result: 'error', message: 'PAN mismatch'});
    }
})(request, response);
